export function chrome(active) {
  const nav = [["My Coast", "mycoast.html"], ["Map", "map.html"], ["Blooms", "station.html"], ["Fisheries", "#"]];
  const bar = document.createElement("header"); bar.className = "bar";
  bar.innerHTML = `<a class="brand" href="mycoast.html" aria-label="Neritic home">${MARK(22)}${WORDMARK}<span class="pv" title="Logo direction B, not approved">mark B · provisional</span></a>
    <nav class="nav" aria-label="Primary">${nav.map(([n, h]) => `<a href="${h}" ${n === active ? 'aria-current="page"' : ""}>${n}</a>`).join("")}</nav>
    <span class="rp">Research preview · not an official source</span>
    <button class="menu" type="button" aria-haspopup="menu">Coastal view · About · Data status <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M1.5 3.5 5 7l3.5-3.5" stroke="currentColor" stroke-width="1.5" fill="none"/></svg></button>`;
  document.body.prepend(bar);
  const tabs = document.createElement("nav"); tabs.className = "tabs"; tabs.setAttribute("aria-label", "Primary");
  tabs.innerHTML = nav.map(([n, h]) => `<a href="${h}" ${n === active ? 'aria-current="page"' : ""}>${n}</a>`).join("");
  document.body.append(tabs);
  if (matchMedia("(max-width: 760px)").matches) bar.querySelector(".menu").innerHTML = "Menu";
}
export const DATA = () => fetch("neritic-data.json").then((r) => r.json());
export const fmtDate = (s, o = { weekday: "short", day: "numeric", month: "short" }) => new Date(s + "T12:00:00Z").toLocaleDateString("en-US", { ...o, timeZone: "UTC" });

/* Segmented control: the indicator slides under the pressed button (transform + width only). */
export function segmented(el, onChange) {
  const ind = document.createElement("span"); ind.className = "ind"; el.prepend(ind);
  const btns = [...el.querySelectorAll("button")];
  const place = (b) => { ind.style.width = b.offsetWidth + "px"; ind.style.transform = `translateX(${b.offsetLeft - 3}px)`; };
  btns.forEach((b) => b.addEventListener("click", () => { btns.forEach((x) => x.setAttribute("aria-pressed", x === b)); place(b); onChange?.(b.dataset.v); }));
  requestAnimationFrame(() => place(btns.find((b) => b.getAttribute("aria-pressed") === "true") ?? btns[0]));
  addEventListener("resize", () => place(btns.find((b) => b.getAttribute("aria-pressed") === "true")));
}

/* Phone sheet: three snap points; a flick (>0.11 px/ms) moves one snap; content scrolls only at the top snap. */
export function sheet(rail, initial = "half") {
  if (!matchMedia("(max-width: 760px)").matches) return;
  const grab = document.createElement("div"); grab.className = "grab"; grab.setAttribute("role", "button"); grab.setAttribute("aria-label", "Resize panel"); grab.tabIndex = 0;
  rail.prepend(grab);
  const H = () => rail.offsetHeight;
  const snaps = () => ({ peek: H() - (+rail.dataset.peek || 132), half: H() * 0.46, full: 0 });
  let cur = initial;
  const set = (name) => { cur = name; rail.style.setProperty("--sheet-y", snaps()[name] + "px"); rail.classList.toggle("full", name === "full"); };
  set(initial);
  let y0 = 0, t0 = 0, start = 0, dragging = false;
  const down = (e) => { if (cur === "full" && rail.scrollTop > 0 && e.target !== grab) return; dragging = true; y0 = e.clientY; t0 = performance.now(); start = snaps()[cur]; rail.classList.add("dragging"); rail.setPointerCapture?.(e.pointerId); };
  const move = (e) => { if (!dragging) return; let y = start + (e.clientY - y0); if (y < 0) y = y / 4; rail.style.setProperty("--sheet-y", y + "px"); };
  const up = (e) => { if (!dragging) return; dragging = false; rail.classList.remove("dragging");
    const dy = e.clientY - y0, v = dy / Math.max(1, performance.now() - t0), order = ["full", "half", "peek"], i = order.indexOf(cur);
    if (Math.abs(v) > 0.11) set(order[Math.min(2, Math.max(0, i + (v > 0 ? 1 : -1)))]);
    else { const y = start + dy, s = snaps(); set(Object.keys(s).reduce((a, k) => Math.abs(s[k] - y) < Math.abs(s[a] - y) ? k : a, "half")); } };
  grab.addEventListener("pointerdown", down); rail.addEventListener("pointerdown", (e) => { if (e.target.closest("a,button,input,select")) return; down(e); });
  addEventListener("pointermove", move); addEventListener("pointerup", up);
  grab.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); set(cur === "full" ? "half" : cur === "half" ? "full" : "half"); } });
  return { set };
}

/* Chart-paper basemap: OpenFreeMap vector tiles restyled; water also carries the hatch that shows wherever no model cell is drawn. */
export const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
export async function baseMap(container, opts) {
  const style = await (await fetch("https://tiles.openfreemap.org/styles/positron")).json();
  for (const l of style.layers) {
    if (l.id === "background") l.paint = { "background-color": "#f6f5f1" };
    else if (l.type === "fill" && /water/.test(l.id)) l.paint = { "fill-color": "#dce6ec" };
    else if (l.type === "fill" && /(landcover|landuse|park|wood|building|aeroway)/.test(l.id)) l.layout = { ...(l.layout || {}), visibility: "none" };
    else if (l.type === "line" && /(road|highway|bridge|tunnel|rail|transit|aeroway|ferry)/.test(l.id)) l.layout = { ...(l.layout || {}), visibility: "none" };
    else if (l.type === "line" && /boundary/.test(l.id)) l.paint = { ...(l.paint||{}), "line-color": "#c7ccd1" };
    else if (l.type === "symbol" && /(poi|road|highway|transport|housenumber|water_name|waterway|aerodrome)/.test(l.id)) l.layout = { ...(l.layout || {}), visibility: "none" };
    else if (l.type === "symbol") l.paint = { ...(l.paint || {}), "text-color": "#56636f", "text-halo-color": "#f6f5f1", "text-halo-width": 1.4 };
  }
  const map = new maplibregl.Map({ container, style, attributionControl: { compact: true }, fadeDuration: 0, ...opts });
  map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");
  map.addControl(new maplibregl.ScaleControl({ unit: "metric", maxWidth: 110 }), "bottom-left");
  await new Promise((r) => map.on("load", r));
  // hatch for "no model value": drawn on the water, under the model cells
  const c = document.createElement("canvas"); c.width = c.height = 8; const g = c.getContext("2d");
  g.fillStyle = "#dce6ec"; g.fillRect(0, 0, 8, 8); g.strokeStyle = "#8a96a2"; g.lineWidth = 1.1; g.beginPath(); g.moveTo(-2, 10); g.lineTo(10, -2); g.moveTo(-2, 2); g.lineTo(2, -2); g.moveTo(6, 10); g.lineTo(10, 6); g.stroke();
  map.addImage("hatch", { width: 8, height: 8, data: g.getImageData(0, 0, 8, 8).data });
  const coast = style.layers.find((l) => l.type === "fill" && /water/.test(l.id));
  map.addLayer({ id: "coastline", type: "line", source: coast.source, "source-layer": coast["source-layer"], paint: { "line-color": "#3f4d5a", "line-width": ["interpolate", ["linear"], ["zoom"], 7, 0.6, 12, 1.4] } });
  return map;
}
/* graticule every 0.1°, labelled on the panel side only */
export function graticule(map, bb, step = 0.1) {
  const f = [];
  for (let x = Math.ceil(bb[0] / step) * step; x <= bb[2]; x += step) f.push({ type: "Feature", properties: { k: Math.round(x * 10) % 5 === 0 ? 1 : 0 }, geometry: { type: "LineString", coordinates: [[x, bb[1]], [x, bb[3]]] } });
  for (let y = Math.ceil(bb[1] / step) * step; y <= bb[3]; y += step) f.push({ type: "Feature", properties: { k: Math.round(y * 10) % 5 === 0 ? 1 : 0 }, geometry: { type: "LineString", coordinates: [[bb[0], y], [bb[2], y]] } });
  map.addSource("grat", { type: "geojson", data: { type: "FeatureCollection", features: f } });
  map.addLayer({ id: "grat", type: "line", source: "grat", paint: { "line-color": "#0b1b2b", "line-opacity": ["case", ["==", ["get", "k"], 1], 0.14, 0.06], "line-width": 0.6 } });
}
/* C-HARM probability: violet lightness ramp, steps of 5 % above 50 % so today's 71–83 % range separates */
export const PROB_STOPS = [[0, "#f4f1f9"], [0.1, "#eee9f6"], [0.2, "#e8e1f3"], [0.3, "#e2d8f1"], [0.4, "#dccfee"], [0.5, "#d3c3ea"], [0.6, "#bba6e2"], [0.65, "#a98fd8"], [0.7, "#9576cb"], [0.75, "#7f5dbb"], [0.8, "#6844a8"], [0.85, "#523193"], [0.9, "#3e227a"], [1, "#2a155a"]];
export const probColor = (v) => { let c = PROB_STOPS[0][1]; for (const [t, col] of PROB_STOPS) if (v >= t) c = col; return c; };
export function cellsGeo(cells, step) {
  const h = step / 2;
  return { type: "FeatureCollection", features: cells.map(([x, y, v], i) => ({ type: "Feature", id: i, properties: { v, c: probColor(v) }, geometry: { type: "Polygon", coordinates: [[[x - h, y - h], [x + h, y - h], [x + h, y + h], [x - h, y + h], [x - h, y - h]]] } })) };
}
export function kmBetween(a, b) { const R = 6371, rad = Math.PI / 180; const x = (b[0] - a[0]) * rad * Math.cos(((a[1] + b[1]) / 2) * rad), y = (b[1] - a[1]) * rad; return R * Math.hypot(x, y); }
export function circle(center, km, n = 96) { const pts = []; for (let i = 0; i <= n; i++) { const t = (i / n) * 2 * Math.PI; pts.push([center[0] + (km / (111.32 * Math.cos(center[1] * Math.PI / 180))) * Math.cos(t), center[1] + (km / 110.57) * Math.sin(t)]); } return { type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [pts] } }; }
